parameters.functionCode:
// Extract attendee details and booked event from Cal.com payload
const payload = items[0].json.body || items[0].json;
const booking = payload.payload || payload;

const attendee = (booking.attendees && booking.attendees[0]) || {};
const name = attendee.name || 'Valued Partner';
const email = attendee.email || '';
const startTime = booking.startTime || '';
const title = booking.title || 'Research-Ready Consultation';
const description = booking.description || '';

// Custom responses from Cal.com booking form
const responses = booking.responses || {};
const useCaseInterest = responses.useCase || responses.interest || 'General / Multi-tier Intelligence';
const orgType = responses.orgType || 'Enterprise / Research Institution';
const hostingPref = responses.hosting || '100% On-Premise GPU Sovereign';

// Match pitch presentation based on use case interest
let pitchUrl = 'https://research-ready.nl/pitch/uc4/';
let showcaseUrl = 'https://research-ready.nl/uc4-supplylens/';

const interestLower = String(useCaseInterest).toLowerCase();
if (interestLower.includes('uc1') || interestLower.includes('citable') || interestLower.includes('research')) {
  pitchUrl = 'https://research-ready.nl/pitch/uc1/';
  showcaseUrl = 'https://research-ready.nl/uc1-citable-research/';
} else if (interestLower.includes('uc12') || interestLower.includes('eval') || interestLower.includes('benchmark')) {
  pitchUrl = 'https://research-ready.nl/pitch/uc12/';
  showcaseUrl = 'https://research-ready.nl/uc12-chainforge/';
} else if (interestLower.includes('uc11') || interestLower.includes('collision') || interestLower.includes('game')) {
  pitchUrl = 'https://container-collision.pages.dev/';
  showcaseUrl = 'https://research-ready.nl/container-collision/';
}

return [{
  json: {
    name,
    email,
    startTime,
    title,
    description,
    useCaseInterest,
    orgType,
    hostingPref,
    pitchUrl,
    showcaseUrl
  }
}];

